import{_ as p,a0 as l,w as o,s as h,ao as r,I as i,x as t,a1 as e,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const m=JSON.parse('{"title":"httpx：一个 Python Web 客户端 | LCTT x X-CMD","titleTemplate":false,"description":"httpx：一个 Python Web 客户端 | LCTT (202203) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"httpx：一个 Python Web 客户端 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"httpx：一个 Python Web 客户端 | LCTT (202203) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202203/20220302 How to use httpx, a web client for Python","title":"httpx：一个 Python Web 客户端","tag":"202203","desc":""},"relativePath":"202203/20220302 How to use httpx, a web client for Python.md","filePath":"[post].md"}'),d={name:"202203/20220302 How to use httpx, a web client for Python.md"};function u(g,s,c,k,b,f){const a=l("Link");return o(),h("div",null,[s[18]||(s[18]=r(`<h1 id="httpx-一个-python-web-客户端" tabindex="-1">httpx：一个 Python Web 客户端 <a class="header-anchor" href="#httpx-一个-python-web-客户端" aria-label="Permalink to “httpx：一个 Python Web 客户端”">​</a></h1><blockquote><p>Python 的 httpx 包是一个用于 HTTP 交互的一个优秀且灵活的模块。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202203/13/102042hmtif0i7g3fg0ir0.jpg" alt=""></p><p>Python 的 <code>httpx</code> 包是一个复杂的 Web 客户端。当你安装它后，你就可以用它来从网站上获取数据。像往常一样，安装它的最简单方法是使用 <code>pip</code> 工具：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ python -m pip install httpx --user</span></span></code></pre></div><p>要使用它，把它导入到 Python 脚本中，然后使用 <code>.get</code> 函数从一个 web 地址获取数据：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import httpx</span></span>
<span class="line"><span>result = httpx.get(&quot;https://httpbin.org/get?hello=world&quot;)</span></span>
<span class="line"><span>result.json()[&quot;args&quot;]</span></span></code></pre></div><p>下面是这个简单脚本的输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    {&#39;hello&#39;: &#39;world&#39;}</span></span></code></pre></div><h3 id="http-响应" tabindex="-1">HTTP 响应 <a class="header-anchor" href="#http-响应" aria-label="Permalink to “HTTP 响应”">​</a></h3><p>默认情况下，<code>httpx</code> 不会在非 200 状态下引发错误。</p><p>试试这个代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>result = httpx.get(&quot;https://httpbin.org/status/404&quot;)</span></span>
<span class="line"><span>result</span></span></code></pre></div><p>结果是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    &lt;Response [404 NOT FOUND]&gt;</span></span></code></pre></div><p>可以明确地返回一个响应。添加这个异常处理：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>try:</span></span>
<span class="line"><span>    result.raise_for_status()</span></span>
<span class="line"><span>except Exception as exc:</span></span>
<span class="line"><span>    print(&quot;woops&quot;, exc)</span></span></code></pre></div><p>下面是结果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    woops Client error &#39;404 NOT FOUND&#39; for url &#39;https://httpbin.org/status/404&#39;</span></span>
<span class="line"><span>    For more information check: https://httpstatuses.com/404</span></span></code></pre></div><h3 id="自定义客户端" tabindex="-1">自定义客户端 <a class="header-anchor" href="#自定义客户端" aria-label="Permalink to “自定义客户端”">​</a></h3><p>除了最简单的脚本之外，使用一个自定义的客户端是有意义的。除了不错的性能改进，比如连接池，这也是一个配置客户端的好地方。</p><p>例如, 你可以设置一个自定义的基本 URL：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>client = httpx.Client(base_url=&quot;https://httpbin.org&quot;)</span></span>
<span class="line"><span>result = client.get(&quot;/get?source=custom-client&quot;)</span></span>
<span class="line"><span>result.json()[&quot;args&quot;]</span></span></code></pre></div><p>输出示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    {&#39;source&#39;: &#39;custom-client&#39;}</span></span></code></pre></div><p>这对用客户端与一个特定的服务器对话的典型场景很有用。例如，使用 <code>base_url</code> 和 <code>auth</code>，你可以为认证的客户端建立一个漂亮的抽象：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>client = httpx.Client(</span></span>
<span class="line"><span>    base_url=&quot;https://httpbin.org&quot;,</span></span>
<span class="line"><span>    auth=(&quot;good_person&quot;, &quot;secret_password&quot;),</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span>result = client.get(&quot;/basic-auth/good_person/secret_password&quot;)</span></span>
<span class="line"><span>result.json()</span></span></code></pre></div><p>输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    {&#39;authenticated&#39;: True, &#39;user&#39;: &#39;good_person&#39;}</span></span></code></pre></div><p>你可以用它来做一件更棒的事情，就是在顶层的 “主” 函数中构建客户端，然后把它传递给其他函数。这可以让其他函数使用客户端，并让它们与连接到本地 WSGI 应用的客户端进行单元测试。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def get_user_name(client):</span></span>
<span class="line"><span>    result = client.get(&quot;/basic-auth/good_person/secret_password&quot;)</span></span>
<span class="line"><span>    return result.json()[&quot;user&quot;]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>get_user_name(client)</span></span>
<span class="line"><span>    &#39;good_person&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def application(environ, start_response):</span></span>
<span class="line"><span>    start_response(&#39;200 OK&#39;, [(&#39;Content-Type&#39;, &#39;application/json&#39;)])</span></span>
<span class="line"><span>    return [b&#39;{&quot;user&quot;: &quot;pretty_good_person&quot;}&#39;]</span></span>
<span class="line"><span>fake_client = httpx.Client(app=application, base_url=&quot;https://fake-server&quot;)</span></span>
<span class="line"><span>get_user_name(fake_client)</span></span></code></pre></div><p>输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    &#39;pretty_good_person&#39;</span></span></code></pre></div><h3 id="尝试-httpx" tabindex="-1">尝试 httpx <a class="header-anchor" href="#尝试-httpx" aria-label="Permalink to “尝试 httpx”">​</a></h3>`,34)),i("p",null,[s[1]||(s[1]=t("请访问 ",-1)),e(a,{href:"https://www.python-httpx.org/"},{default:n(()=>[...s[0]||(s[0]=[t("python-httpx.org",-1)])]),_:1}),s[2]||(s[2]=t(" 了解更多信息、文档和教程。我发现它是一个与 HTTP 交互的优秀而灵活的模块。试一试，看看它能为你做什么。",-1))]),s[19]||(s[19]=i("hr",null,null,-1)),i("p",null,[s[4]||(s[4]=t("via: ",-1)),e(a,{href:"https://opensource.com/article/22/3/python-httpx"},{default:n(()=>[...s[3]||(s[3]=[t("https://opensource.com/article/22/3/python-httpx",-1)])]),_:1})]),i("p",null,[s[9]||(s[9]=t("作者：",-1)),e(a,{href:"https://opensource.com/users/moshez"},{default:n(()=>[...s[5]||(s[5]=[t("Moshe Zadka",-1)])]),_:1}),s[10]||(s[10]=t(" 选题：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[6]||(s[6]=[t("lujun9972",-1)])]),_:1}),s[11]||(s[11]=t(" 译者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:n(()=>[...s[7]||(s[7]=[t("geekpi",-1)])]),_:1}),s[12]||(s[12]=t(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[8]||(s[8]=[t("wxy",-1)])]),_:1})]),i("p",null,[s[15]||(s[15]=t("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[13]||(s[13]=[t("LCTT",-1)])]),_:1}),s[16]||(s[16]=t(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:n(()=>[...s[14]||(s[14]=[t("Linux中国",-1)])]),_:1}),s[17]||(s[17]=t(" 荣誉推出",-1))])])}const C=p(d,[["render",u]]);export{m as __pageData,C as default};
